editorial:
## Method and reasoning
Compress values, then sort queries by the block of their left endpoint. Within each block sort by right endpoint, alternating the direction to reduce endpoint motion. Maintain the frequency of every rank in the current window and change the distinct count only on transitions to or from zero.

## Walk through the sample
The full sample has frequencies 1→2, 4→2, −1→1. Removing the first 1 leaves the distinct count unchanged. Removing the last −1 decreases it. These zero crossings suffice regardless of the offline query order.

## Complexity
For block size B, endpoint work is O(qB+n²/B), with O((n+q) log(n+q)) sorting and O(n+q) storage.

## Reference implementation
~~~
#include <bits/stdc++.h>
using namespace std;

struct Query {
    int l, r, id;
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<int> a(n);
    for (auto &x : a)
        cin >> x;
    auto keys = a;
    sort(keys.begin(), keys.end());
    keys.erase(unique(keys.begin(), keys.end()), keys.end());
    for (auto &x : a)
        x = lower_bound(keys.begin(), keys.end(), x) - keys.begin();
    int block = max(1, int(n / sqrt(q)));
    vector<Query> queries(q);
    for (int i = 0; i < q; ++i) {
        auto &v = queries[i];
        cin >> v.l >> v.r;
        --v.l;
        --v.r;
        v.id = i;
    }
    sort(queries.begin(), queries.end(), [&](Query a, Query b) {
        int i = a.l / block, j = b.l / block;
        return i != j ? i < j : i % 2 ? a.r > b.r : a.r < b.r;
    });
    vector<int> freq(keys.size()), answer(q);
    int l = 0, r = -1, count = 0;
    auto add = [&](int i) { count += ++freq[a[i]] == 1; };
    auto remove = [&](int i) { count -= --freq[a[i]] == 0; };
    for (auto v : queries) {
        while (l > v.l)
            add(--l);
        while (r < v.r)
            add(++r);
        while (l < v.l)
            remove(l++);
        while (r > v.r)
            remove(r--);
        answer[v.id] = count;
    }
    for (int x : answer)
        cout << x << '\n';
}
~~~
